import { describe, test, expect } from 'vitest';
import GBNF, { GBNF as named, ParseState, RuleChar, RuleCharExclude, RuleEnd, RuleType, isRange, GrammarParseError, InputParseError } from 'gbnf';

describe('smoke', () => {
  test('exports + parse state surface', () => {
    const state = GBNF('root ::= "ab" | [x-z]');
    expect(state).toBeInstanceOf(ParseState);
    expect(named).toBe(GBNF);
    expect(state.size).toBe(2);
    expect(state.grammar).toBe('root ::= "ab" | [x-z]');
    expect([...state.rules()]).toEqual([{ type: 'char', value: [97] }, { type: 'char', value: [[120, 122]] }]);
    expect(state.add('a').add('b').size).toBe(1);
    expect([...state.add('y')]).toEqual([{ type: 'end' }]);
    expect(new RuleChar([1]).type).toBe(RuleType.CHAR);
    expect(new RuleCharExclude([1]).type).toBe(RuleType.CHAR_EXCLUDE);
    expect(new RuleEnd().type).toBe(RuleType.END);
    expect(isRange([1, 2])).toBe(true);
    expect(isRange([1, 2, 3])).toBe(false);
  });

  test('initial string arg and code point input', () => {
    expect([...GBNF('root ::= "foo"', 'fo')]).toEqual([{ type: 'char', value: [111] }]);
    expect([...GBNF('root ::= "foo"', [102, 111])]).toEqual([{ type: 'char', value: [111] }]);
    expect([...GBNF('root ::= "foo"', 102)]).toEqual([{ type: 'char', value: [111] }]);
  });

  test('errors expose their metadata', () => {
    try { GBNF('root = "foo"'); } catch (err) {
      const e = err as GrammarParseError;
      expect(e).toBeInstanceOf(GrammarParseError);
      expect(e.name).toBe('GrammarParseError');
      expect([e.pos, e.reason, e.grammar]).toEqual([5, 'Expecting ::= at 5', 'root = "foo"']);
      expect(e.message).toBe('Failed to parse grammar: Expecting ::= at 5\n\nroot = "foo"\n     ^');
    }
    const state = GBNF('root ::= "bar"').add('ba');
    try { state.add('z'); } catch (err) {
      const e = err as InputParseError;
      expect(e).toBeInstanceOf(InputParseError);
      expect(e.src).toBe('baz');
      expect(e.message).toBe('Failed to parse input string:\n\nbaz\n  ^');
      expect(e.errorForMostRecentInput).toBe('Failed to parse input string:\n\nz\n^');
    }
    expect(() => GBNF('foo ::= "foo"')).toThrowError(
      new GrammarParseError('foo ::= "foo"', 0, 'Grammar does not contain a root symbol. Available symbols are: ["foo"]'));
  });

  test('multiline grammars and comments parse', () => {
    const grammar = '# a comment\nroot ::= greeting " " name\ngreeting ::= "hi" | "yo"\nname ::= [a-z]+\n';
    let state = GBNF(grammar);
    for (const ch of 'hi bob') state = state.add(ch);
    expect([...state]).toEqual([{ type: 'char', value: [[97, 122]] }, { type: 'end' }]);
  });

  test('escapes', () => {
    expect([...GBNF('root ::= "\\t\\r\\n\\x41\\u00e9\\\\\\"[]"')]).toEqual([{ type: 'char', value: [9] }]);
    let s = GBNF('root ::= "\\t\\x41\\u00e9"');
    s = s.add('\tAé');
    expect([...s]).toEqual([{ type: 'end' }]);
  });
});
EOF
